// Брендовая база, часть 12: лапша и пюре быстрого приготовления,
// сухие завтраки, детское питание (соки, пюре, каши, молочка),
// соусы и кетчупы, лаваш, маринованные продукты и консервация —
// расширение по просьбе Кати 28.11.
//
// КФЖУ — на 100 г / 100 мл; значения типовые по виду продукта,
// ккал считает фабрика f() по Атуотеру (4Б + 9Ж + 4У, клетчатка 2).
// al — короткие алиасы для поиска (голос/текст и «по составу»).

const f = (id, emoji, name, p, f_, c, fib, sug, dg, tags, al) => ({
  id,
  emoji,
  name,
  kcal: Math.round(p * 4 + f_ * 9 + (c - fib) * 4 + fib * 2),
  p,
  f: f_,
  c,
  fib,
  sug,
  defaultGrams: dg,
  tags,
  al,
})

